def __setattr__(self, name, value):
    if name == '_wrapped':
        self.__dict__.clear()
    else:
        self.__dict__.pop(name, None)
    if name == 'SIGNED_COOKIE_LEGACY_SALT_FALLBACK':
        _show_settings_deprecation_warning(SIGNED_COOKIE_LEGACY_SALT_DEPRECATED_MSG, RemovedInDjango70Warning)
    if name == 'USE_BLANK_CHOICE_DASH':
        _show_settings_deprecation_warning(USE_BLANK_CHOICE_DASH_DEPRECATED_MSG, RemovedInDjango70Warning)
    if name == 'MAILERS':
        for setting in DEPRECATED_EMAIL_SETTINGS:
            self.__dict__.pop(setting, None)
    if name in DEPRECATED_EMAIL_SETTINGS:
        _show_settings_deprecation_warning(EMAIL_SETTING_DEPRECATED_MSG.format(name=name), RemovedInDjango70Warning)
    super().__setattr__(name, value)

