def handle_fk_field(self, obj, field):
    self._start_relational_field(field)
    related_att = getattr(obj, field.attname)
    if related_att is not None:
        if self.use_natural_foreign_keys and (natural_key_value := self._resolve_fk_natural_key(obj, field)):
            for key_value in natural_key_value:
                self.xml.startElement('natural', {})
                if key_value is None:
                    self.xml.addQuickElement('None')
                else:
                    self.xml.characters(str(key_value))
                self.xml.endElement('natural')
        else:
            self.xml.characters(str(related_att))
    else:
        self.xml.addQuickElement('None')
    self.xml.endElement('field')
    self.indent_level -= 1

def _handle_m2m_field_node(self, node, field):
    model = field.remote_field.model
    default_manager = model._default_manager
    if hasattr(default_manager, 'get_by_natural_key'):

        def m2m_convert(n):
            keys = getChildrenByTagName(n, 'natural')
            if keys:
                field_value = []
                for k in keys:
                    if getChildrenByTagName(k, 'None'):
                        field_value.append(None)
                    else:
                        field_value.append(getInnerText(k).strip())
                obj_pk = default_manager.db_manager(self.db).get_by_natural_key(*field_value).pk
            else:
                obj_pk = model._meta.pk.to_python(n.getAttribute('pk'))
            return obj_pk
    else:

        def m2m_convert(n):
            return model._meta.pk.to_python(n.getAttribute('pk'))
    values = []
    try:
        for c in getChildrenByTagName(node, 'object'):
            values.append(m2m_convert(c))
    except SuspiciousOperation:
        raise
    except Exception as e:
        if isinstance(e, ObjectDoesNotExist) and self.handle_forward_references:
            return base.DEFER_FIELD
        else:
            raise base.M2MDeserializationError(e, c)
    else:
        return values

