def to_python(self, value):
    if value in self.empty_values:
        return None
    if self.localize:
        value = formats.sanitize_separators(value)
    try:
        value = Decimal(str(value))
    except DecimalException:
        raise ValidationError(self.error_messages['invalid'], code='invalid')
    return value

def validate(self, value):
    if self.required and (not value):
        raise ValidationError(self.error_messages['required'], code='required')
    for val in OrderedSet(value):
        if not self.valid_value(val):
            raise ValidationError(self.error_messages['invalid_choice'], code='invalid_choice', params={'value': val})

def get_initial_for_field(self, field, field_name):
    value = self.initial.get(field_name, field.initial)
    if callable(value):
        value = value()
    if isinstance(value, (datetime.datetime, datetime.time)) and (not field.widget.supports_microseconds):
        value = value.replace(microsecond=0)
    return value

