    d = getdata(a)
    if self.domain is not None:
        with np.errstate(divide='ignore', invalid='ignore'):
            result = self.f(d, *args, **kwargs)
        m = ~umath.isfinite(result)
        m |= self.domain(d)
        m |= getmask(a)
    else:
        with np.errstate(divide='ignore', invalid='ignore'):
            result = self.f(d, *args, **kwargs)
        m = getmask(a)
    if not result.ndim:
