def mask_missing(arr: ArrayLike, value) -> npt.NDArray[np.bool_]:
    dtype, value = infer_dtype_from(value)
    if isinstance(arr.dtype, (BaseMaskedDtype, ArrowDtype)) and lib.is_float(value) and np.isnan(value) and (not is_nan_na()):
        if arr.dtype.kind == 'f':
            if isinstance(arr.dtype, BaseMaskedDtype):
                mask = np.isnan(arr._data) & ~arr.isna()
                return mask
            else:
                import pyarrow.compute as pc
                mask = pc.is_nan(arr._pa_array).fill_null(False).to_numpy()
                return mask
        elif arr.dtype.kind in 'iu':
            mask = np.zeros(arr.shape, dtype=bool)
            return mask
    if isna(value):
        return isna(arr)
    mask = np.zeros(arr.shape, dtype=bool)
    if is_numeric_dtype(arr.dtype) and (not is_bool_dtype(arr.dtype)) and lib.is_bool(value):
        pass
    elif is_bool_dtype(arr.dtype) and is_numeric_dtype(dtype) and (not lib.is_bool(value)):
        pass
    elif is_numeric_dtype(arr.dtype) and isinstance(value, str):
        pass
    elif is_object_dtype(arr.dtype):
        arr_mask = ~isna(arr)
        mask[arr_mask] = arr[arr_mask] == value
    else:
