def combine_first(self, other) -> Series:
    from pandas.core.reshape.concat import concat
    if self.dtype == other.dtype:
        if self.index.equals(other.index):
            return self.mask(self.isna(), other)
    new_index = self.index.union(other.index)
    this = self
    keep_other = other.index.difference(this.index[notna(this)])
    keep_this = this.index.difference(keep_other)
    this = this.reindex(keep_this)
    other = other.reindex(keep_other)
    if this.dtype.kind == 'M' and other.dtype.kind != 'M':
        other = to_datetime(other)
        warnings.warn("Silently casting non-datetime 'other' to datetime in Series.combine_first is deprecated and will be removed in a future version. Explicitly cast before calling combine_first instead.", Pandas4Warning, stacklevel=find_stack_level())
    combined = concat([this, other])
    combined = combined.reindex(new_index)
    return combined.__finalize__(self, method='combine_first')

