def visit_Slice(self, node, **kwargs) -> slice:
    lower = node.lower
    if lower is not None:
        lower = self.visit(lower).value
    upper = node.upper
    if upper is not None:
        upper = self.visit(upper).value
    step = node.step
    if step is not None:
        step = self.visit(step).value
    return slice(lower, upper, step)

def update(self, value) -> None:
    key = self.name
    if isinstance(key, str):
        self.env.swapkey(self.local_name, key, new_value=value)
    self.value = value

def astype_array_safe(values: ArrayLike, dtype: Dtype, copy: bool=False, errors: IgnoreRaise='raise') -> ArrayLike:
    errors_legal_values = ('raise', 'ignore')
    if errors not in errors_legal_values:
        invalid_arg = f"Expected value of kwarg 'errors' to be one of {list(errors_legal_values)}. Supplied value is '{errors}'"
        raise ValueError(invalid_arg)
    if inspect.isclass(dtype) and issubclass(dtype, ExtensionDtype):
        msg = f"Expected an instance of {dtype.__name__}, but got the class instead. Try instantiating 'dtype'."
        raise TypeError(msg)
    dtype = pandas_dtype(dtype)
    if isinstance(dtype, NumpyEADtype):
        dtype = dtype.numpy_dtype
    try:
        new_values = astype_array(values, dtype, copy=copy)
    except (ValueError, TypeError):
        if errors == 'ignore':
            new_values = values
        else:
            raise
    return new_values

