@set_module('pandas')
def concat(objs: Iterable[Series | DataFrame] | Mapping[HashableT, Series | DataFrame], *, axis: Axis=0, join: str='outer', ignore_index: bool=False, keys: Iterable[Hashable] | None=None, levels=None, names: list[HashableT] | None=None, verify_integrity: bool=False, sort: bool | lib.NoDefault=lib.no_default, copy: bool | lib.NoDefault=lib.no_default) -> DataFrame | Series:
    if ignore_index and keys is not None:
        raise ValueError(f'Cannot set ignore_index={ignore_index!r} and specify keys. Either should be used.')
    if copy is not lib.no_default:
        warnings.warn('The copy keyword is deprecated and will be removed in a future version. Copy-on-Write is active in pandas since 3.0 which utilizes a lazy copy mechanism that defers copies until necessary. Use .copy() to make an eager copy if necessary.', Pandas4Warning, stacklevel=find_stack_level())
    if join == 'outer':
        intersect = False
    elif join == 'inner':
        intersect = True
    else:
        raise ValueError('Only can inner (intersect) or outer (union) join the other axis')
    objs, keys, ndims = _clean_keys_and_objs(objs, keys)
