def _num2excel(self, index: int) -> str:
    if index < 0:
        raise ValueError(f'Index cannot be negative: {index}')
    column_name = ''
    while index > 0 or not column_name:
        index, remainder = divmod(index, 26)
        column_name = chr(65 + remainder) + column_name
    return column_name

