def on_rm_rf_error(func: Callable[..., Any] | None, path: str, excinfo: BaseException | tuple[type[BaseException], BaseException, types.TracebackType | None], *, start_path: Path) -> bool:
    if isinstance(excinfo, BaseException):
        exc = excinfo
    else:
        exc = excinfo[1]
    if isinstance(exc, FileNotFoundError):
        return False
    if not isinstance(exc, PermissionError):
        warnings.warn(PytestWarning(f'(rm_rf) error removing {path}\n{type(exc)}: {exc}'))
        return False
    p = Path(path)
    if func in (os.open, os.scandir):
        parent_changed = False
        parent = p.parent
        if parent not in (p, start_path):
            parent_changed = _chmod_rwx(str(parent))
        path_changed = _chmod_rwx(str(p))
        if not (parent_changed or path_changed):
            return False
        if p.is_dir():
            rm_rf(p)
        else:
            try:
                os.unlink(str(p))
            except OSError:
                return False
        return True
    if func not in (os.rmdir, os.remove, os.unlink):
        warnings.warn(PytestWarning(f'(rm_rf) unknown function {func} when removing {path}:\n{type(exc)}: {exc}'))
        return False
    if p.is_file():
        for parent in p.parents:
            _chmod_rwx(str(parent))
            if parent == start_path:
                break
    _chmod_rwx(str(path))
    func(path)
    return True

