def matchreport(self, inamepart: str='', names: str | Iterable[str]=('pytest_runtest_logreport', 'pytest_collectreport'), when: str | None=None) -> CollectReport | TestReport:
    values = []
    for rep in self.getreports(names=names):
        if not when and rep.when != 'call' and rep.passed:
            continue
        if when and rep.when != when:
            continue
        if not inamepart or inamepart in rep.nodeid.split('::'):
            values.append(rep)
    if not values:
        raise ValueError(f'could not find test report matching {inamepart!r}: no test reports at all!')
    if len(values) > 1:
        raise ValueError(f'found 2 or more testreports matching {inamepart!r}: {values}')
    return values[0]

