        if setup is not None:
            try:
                setup()
            except Exception:
                cleanup()
                process_teardown_exceptions()
                raise
        yield
        try:
            if teardown is not None:
                teardown()
        finally:
            cleanup()
            process_teardown_exceptions()
    fixtures.register_fixture(name=f'_unittest_setUpClass_fixture_{cls.__qualname__}', func=unittest_setup_class_fixture, node=self, scope='class', autouse=True)

