def parse_hookimpl_opts(self, plugin: _PluggyPlugin, name: str) -> HookimplOpts | None:
    if not name.startswith('pytest_'):
        return None
    if name == 'pytest_plugins':
        return None
    opts = super().parse_hookimpl_opts(plugin, name)
    if opts is not None:
        return opts
    method = getattr(plugin, name)
    if not inspect.isroutine(method):
        return None
    legacy = _get_legacy_hook_marks(method, 'impl', ('tryfirst', 'trylast', 'optionalhook', 'hookwrapper'))
    return cast(HookimplOpts, legacy)

