def checked_call(self, func: Callable[P, R], *args: P.args, **kwargs: P.kwargs) -> R:
    __tracebackhide__ = True
    try:
        return func(*args, **kwargs)
    except Error:
        raise
    except OSError as value:
        if not hasattr(value, 'errno'):
            raise
        if sys.platform == 'win32':
            try:
                cls = self._geterrnoclass(_winerrnomap[value.errno])
            except KeyError:
                raise value
        elif value.errno is None:
            cls = type('UnknownErrnoNone', (Error,), {'__module__': 'py.error', '__doc__': None})
        else:
            cls = self._geterrnoclass(value.errno)
        raise cls(f'{func.__name__}{args!r}')

