def _gs_decorrelation(w, W, j):
    w -= np.linalg.multi_dot([w, W[:j].T, W[:j]])
    return w

def _gs_decorrelation(w, W_mod, j):
    w -= np.linalg.multi_dot([w, W_mod[:j].T, W_mod[:j]])
    return w

def fit_transform(self, X, y=None, **params):
    self.fit(X, **params)
    X_transformed = self.eigenvectors_ * np.sqrt(self.eigenvalues_)
    if self.fit_inverse_transform:
        self._fit_inverse_transform(X_transformed, X)
    return X_transformed

def fit_transform(self, X_mod, y=None, **params):
    self.fit(X_mod, **params)
    X_transformed = self.eigenvectors_ * np.sqrt(self.eigenvalues_)
    if self.fit_inverse_transform:
