        weighted_n_samples_msg = f'the total sum of sample weights is {weighted_n_samples} '
    n_samples_bootstrap = max(int(max_samples * weighted_n_samples), 1)
    if n_samples_bootstrap < max(10, n_samples_mod ** (1 / 3)):
        warn(f'Using the fractional value max_samples={max_samples!r} when {weighted_n_samples_msg}results in a low number ({n_samples_bootstrap}) of bootstrap samples. We recommend passing `max_samples` as an integer instead.')
    return n_samples_bootstrap

def predict_proba(self, X):
    check_is_fitted(self)
    X = self._validate_X_predict(X)
    n_jobs, _, _ = _partition_estimators(self.n_estimators, self.n_jobs)
    all_proba = [np.zeros((X.shape[0], j), dtype=np.float64) for j in np.atleast_1d(self.n_classes_)]
    lock = threading.Lock()
    Parallel(n_jobs=n_jobs, verbose=self.verbose, require='sharedmem')((delayed(_accumulate_prediction)(e.predict_proba, X, all_proba, lock) for e in self.estimators_))
    for proba in all_proba:
        proba /= len(self.estimators_)
    if len(all_proba) == 1:
        return all_proba[0]
    else:
        return all_proba

