    if n_classes == 2:
        for pred in self.staged_decision_function(X):
            yield np.array(classes.take(pred > 0, axis=0))
    else:
        for pred in self.staged_decision_function(X):
            yield np.array(classes.take(np.argmax(pred, axis=1), axis=0))

