@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y):
    X, y = validate_data(self, X, y, validate_separately=({'accept_sparse': True, 'ensure_min_samples': 2}, {'accept_sparse': False, 'ensure_2d': False}))
    check_classification_targets(y)
    y = LabelEncoder().fit_transform(y)
    if self.n_components is not None and self.n_components > X.shape[1]:
        raise ValueError(f'The preferred dimensionality of the projected space `n_components` ({self.n_components}) cannot be greater than the given data dimensionality ({X.shape[1]})!')
    if self.warm_start and hasattr(self, 'components_') and (self.components_.shape[1] != X.shape[1]):
        raise ValueError(f'The new inputs dimensionality ({X.shape[1]}) does not match the input dimensionality of the previously learned transformation ({self.components_.shape[1]}).')
    init = self.init
    if isinstance(init, np.ndarray):
        init = check_array(init)
        if init.shape[1] != X.shape[1]:
            raise ValueError(f'The input dimensionality ({init.shape[1]}) of the given linear transformation `init` must match the dimensionality of the given inputs `X` ({X.shape[1]}).')
        if init.shape[0] > init.shape[1]:
            raise ValueError(f'The output dimensionality ({init.shape[0]}) of the given linear transformation `init` cannot be greater than its input dimensionality ({init.shape[1]}).')
        if self.n_components is not None and self.n_components != init.shape[0]:
            raise ValueError(f'The preferred dimensionality of the projected space `n_components` ({self.n_components}) does not match the output dimensionality of the given linear transformation `init` ({init.shape[0]})!')
    self.random_state_ = check_random_state(self.random_state)
    t_train = time.time()
    same_class_mask = y[:, np.newaxis] == y[np.newaxis, :]
    transformation = np.ravel(self._initialize(X, y, init))
    disp = self.verbose - 2 if self.verbose > 1 else -1
    optimizer_params = {'method': 'L-BFGS-B', 'fun': self._loss_grad_lbfgs, 'args': (X, same_class_mask, -1.0), 'jac': True, 'x0': transformation, 'tol': self.tol, 'options': dict(maxiter=self.max_iter, **_get_additional_lbfgs_options_dict('disp', disp)), 'callback': self._callback}
    self.n_iter_ = 0
    opt_result = minimize(**optimizer_params)
    self.components_ = opt_result.x.reshape(-1, X.shape[1])
    t_train = time.time() - t_train
    if self.verbose:
        cls_name = self.__class__.__name__
        if not opt_result.success:
            warn('[{}] NCA did not converge: {}'.format(cls_name, opt_result.message), ConvergenceWarning)
        print('[{}] Training took {:8.2f}s.'.format(cls_name, t_train))
    return self

