def inverse_transform(self, X):
    check_is_fitted(self)
    X = check_array(X, accept_sparse=('csr', 'csc'), copy=self.copy, dtype=FLOAT_DTYPES, force_writeable=True, ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        if self.with_scaling:
