def inspect(subject: Any, raiseerr: bool=True) -> Any:
    type_ = type(subject)
    for cls in type_.__mro__:
        if cls in _registrars:
            reg = _registrars.get(cls, None)
            if reg is None:
                continue
            elif reg is True:
                return subject
            ret = reg(subject)
            if ret is not None:
                return ret
    else:
        reg = ret = None
    if raiseerr and (reg is None or ret is None):
        raise exc.NoInspectionAvailable('No inspection system is available for object of type %s' % type_)
    return ret

