def instances(cursor: CursorResult[Unpack[TupleAny]], context: QueryContext) -> Result[Unpack[TupleAny]]:
    context.runid = _new_runid()
    if context.top_level_context:
        is_top_level = False
        context.post_load_paths = context.top_level_context.post_load_paths
    else:
        is_top_level = True
        context.post_load_paths = {}
    compile_state = context.compile_state
    filtered = compile_state._has_mapper_entities
    single_entity = not context.load_options._only_return_tuples and len(compile_state._entities) == 1 and compile_state._entities[0].supports_single_entity
    try:
        process, labels, extra = list(zip(*[query_entity.row_processor(context, cursor) for query_entity in context.compile_state._entities]))
        if context.yield_per and (context.loaders_require_buffering or context.loaders_require_uniquing):
            raise sa_exc.InvalidRequestError("Can't use yield_per with eager loaders that require uniquing or row buffering, e.g. joinedload() against collections or subqueryload().  Consider the selectinload() strategy for better flexibility in loading objects.")
    except Exception:
        with util.safe_reraise():
            cursor.close()

    def _not_hashable(datatype, *, legacy=False, uncertain=False):
        if not legacy:

            def go(obj):
                if uncertain:
                    try:
                        return hash(obj)
                    except:
                        pass
                raise sa_exc.InvalidRequestError(f"Can't apply uniqueness to row tuple containing value of type {datatype!r}; {('the values returned appear to be' if uncertain else 'this datatype produces')} non-hashable values")
            return go
        elif not uncertain:
            return id
        else:
            _use_id = False

            def go(obj):
                nonlocal _use_id
                if not _use_id:
                    try:
                        return hash(obj)
                    except:
                        pass
                    _use_id = True
                return id(obj)
            return go
    _uniquing_is_active = False

    def _create_unique_filters(result):
        nonlocal _uniquing_is_active
        if result._yield_per:
            raise sa_exc.InvalidRequestError("Can't use the ORM yield_per feature in conjunction with unique()")
        _uniquing_is_active = True
        return [_not_hashable(ent.column.type, legacy=context.load_options._legacy_uniquing, uncertain=ent._null_column_type) if not ent.use_id_for_hash and (ent._non_hashable_value or ent._null_column_type) else id if ent.use_id_for_hash else None for ent in context.compile_state._entities]
    row_metadata = SimpleResultMetaData(labels, extra, _create_unique_filters=_create_unique_filters)

    def chunks(size):
        while True:
            yield_per = size
            context.partials = {}
            if yield_per:
                if _uniquing_is_active:
                    raise sa_exc.InvalidRequestError("Can't use the ORM yield_per feature in conjunction with unique()")
                fetch = cursor.fetchmany(yield_per)
                if not fetch:
                    break
            else:
                fetch = cursor._raw_all_tuples()
            if single_entity:
                proc = process[0]
                rows = [proc(row) for row in fetch]
            else:
                rows = [tuple([proc(row) for proc in process]) for row in fetch]
            if is_top_level:
                if yield_per:
                    top_level_post_loads = list(context.post_load_paths.items())
                while context.post_load_paths:
                    post_loads = list(context.post_load_paths.items())
                    context.post_load_paths.clear()
                    for path, post_load in post_loads:
                        post_load.invoke(context, path)
                if yield_per:
                    context.post_load_paths.clear()
                    context.post_load_paths.update(top_level_post_loads)
            yield rows
            if not yield_per:
                break
    if context.execution_options.get('prebuffer_rows', False):
        _prebuffered = list(chunks(None))

        def chunks(size):
            return iter(_prebuffered)
    result = ChunkedIteratorResult(row_metadata, chunks, source_supports_scalars=single_entity, raw=cursor, dynamic_yield_per=cursor.context._is_server_side, context=context)
    result._attributes = result._attributes.union(dict(filtered=filtered, is_single_entity=single_entity))
    if context.requires_uniquing:

        def require_unique(obj):
            raise sa_exc.InvalidRequestError('The unique() method must be invoked on this Result, as it contains results that include joined eager loads against collections')
        result._unique_filter_state = (set(), require_unique)
    if context.yield_per:
        result.yield_per(context.yield_per)
    return result

