def get_bind(self, mapper: Optional[_EntityBindKey[_O]]=None, *, clause: Optional[ClauseElement]=None, bind: Optional[_SessionBind]=None, _sa_skip_events: Optional[bool]=None, _sa_skip_for_implicit_returning: bool=False, **kw: Any) -> Union[Engine, Connection]:
    if bind:
        return bind
    elif not self.__binds and self.bind:
        return self.bind
    if mapper is None and clause is None:
        if self.bind:
            return self.bind
        else:
            raise sa_exc.UnboundExecutionError('This session is not bound to a single Engine or Connection, and no context was provided to locate a binding.')
    if mapper is not None:
        try:
            inspected_mapper = inspect(mapper)
        except sa_exc.NoInspectionAvailable as err:
            if isinstance(mapper, type):
                raise exc.UnmappedClassError(mapper) from err
            else:
                raise
    else:
        inspected_mapper = None
    if self.__binds:
        if inspected_mapper:
            for cls in inspected_mapper.class_.__mro__:
                if cls in self.__binds:
                    return self.__binds[cls]
            if clause is None:
                clause = inspected_mapper.persist_selectable
        if clause is not None:
            plugin_subject = clause._propagate_attrs.get('plugin_subject', None)
            if plugin_subject is not None:
                for cls in plugin_subject.mapper.class_.__mro__:
                    if cls in self.__binds:
                        return self.__binds[cls]
            for obj in visitors.iterate(clause):
                if obj in self.__binds:
                    if TYPE_CHECKING:
                        assert isinstance(obj, Table)
                    return self.__binds[obj]
    if self.bind:
        return self.bind
    context = []
    if inspected_mapper is not None:
        context.append(f'mapper {inspected_mapper}')
    if clause is not None:
        context.append('SQL expression')
    raise sa_exc.UnboundExecutionError(f"Could not locate a bind configured on {', '.join(context)} or this Session.")

