def _adjust_for_extra_criteria(self, context: QueryContext) -> Load:
    for value in self.context:
        if value._extra_criteria:
            break
    else:
        return self
    replacement_cache_key = context.user_passed_query._generate_cache_key()
    if replacement_cache_key is None:
        return self
    orig_query = context.compile_state.select_statement
    orig_cache_key = orig_query._generate_cache_key()
    assert orig_cache_key is not None

    def process(opt: _LoadElement, replacement_cache_key: CacheKey, orig_cache_key: CacheKey) -> _LoadElement:
        cloned_opt = opt._clone()
        cloned_opt._extra_criteria = tuple((replacement_cache_key._apply_params_to_element(orig_cache_key, crit) for crit in cloned_opt._extra_criteria))
        return cloned_opt
    cloned = self._clone()
    cloned.context = tuple((process(value, replacement_cache_key, orig_cache_key) if value._extra_criteria else value for value in self.context))
    return cloned

@staticmethod
def _reconcile(replacement: _LoadElement, existing: _LoadElement) -> _LoadElement:
    if replacement._reconcile_to_other:
        return existing
    elif replacement._reconcile_to_other is False:
        return replacement
    elif existing._reconcile_to_other:
        return replacement
    elif existing._reconcile_to_other is False:
        return existing
    if existing is replacement:
        return replacement
    elif existing.strategy == replacement.strategy and existing.local_opts == replacement.local_opts:
        return replacement
    elif replacement.is_opts_only:
        existing = existing._clone()
        existing.local_opts = existing.local_opts.union(replacement.local_opts)
        existing._extra_criteria += replacement._extra_criteria
        return existing
    elif existing.is_opts_only:
        replacement = replacement._clone()
        replacement.local_opts = replacement.local_opts.union(existing.local_opts)
        replacement._extra_criteria += existing._extra_criteria
        return replacement
    elif replacement.path.is_token:
        return replacement
    raise sa_exc.InvalidRequestError(f'Loader strategy replacement {replacement._to_option_method_string()} is in conflict with existing strategy {existing._to_option_method_string()}')

