def _new_annotation_type(cls: Type[SupportsWrappingAnnotations], base_cls: Type[Annotated]) -> Type[Annotated]:
    if issubclass(cls, Annotated):
        return cls
    elif cls in annotated_classes:
        return annotated_classes[cls]
    for super_ in cls.__mro__:
        if super_ in annotated_classes:
            base_cls = annotated_classes[super_]
            break
    annotated_classes[cls] = anno_cls = cast(Type[Annotated], type('Annotated%s' % cls.__name__, (base_cls, cls), {}))
    globals()['Annotated%s' % cls.__name__] = anno_cls
    if '_traverse_internals' in cls.__dict__:
        anno_cls._traverse_internals = list(cls._traverse_internals) + [('_annotations', InternalTraversal.dp_annotations_key)]
    elif cls.__dict__.get('inherit_cache', False):
        anno_cls._traverse_internals = list(cls._traverse_internals) + [('_annotations', InternalTraversal.dp_annotations_key)]
    if cls.__dict__.get('inherit_cache', False):
        anno_cls.inherit_cache = True
    elif 'inherit_cache' in cls.__dict__:
        anno_cls.inherit_cache = cls.__dict__['inherit_cache']
    anno_cls._is_column_operators = issubclass(cls, operators.ColumnOperators)
    return anno_cls

def _entity_namespace_key_search_all(entities: Collection[Any], key: str) -> SQLCoreOperations[Any]:
    match_: SQLCoreOperations[Any] | None = None
    for entity in entities:
        ns = _entity_namespace(entity)
        if hasattr(ns, key):
            if match_ is not None:
                entity_desc = ', '.join((str(e) for e in list(entities)[:3]))
                if len(entities) > 3:
                    entity_desc += f', ... ({len(entities)} total)'
                raise exc.AmbiguousColumnError(f'Attribute name "{key}" is ambiguous; it exists in multiple FROM clause entities ({entity_desc}). Use filter() with explicit column references instead of filter_by().')
            match_ = getattr(ns, key)
    if match_ is None:
        entity_desc = ', '.join((str(e) for e in list(entities)[:3]))
        if len(entities) > 3:
            entity_desc += f', ... ({len(entities)} total)'
        raise exc.InvalidRequestError(f'None of the FROM clause entities have a property "{key}". Searched entities: {entity_desc}')
    return match_

